[{"doc_id": "doc_5755", "sent_idx": 123, "cleaned_version": 1, "sentence": "Here is a simple Perl script named arbitrary.pl that can be ran to easily lay out tasks on nodes as they are in SLURM_JOB_NODELIST.
#!/usr/bin/perl
my @tasks = split(',', $ARGV[0]);
my @nodes = `scontrol show hostnames $SLURM_JOB_NODELIST`;
my $node_cnt = $#nodes + 1;
my $task_cnt = $#tasks + 1;
if ($node_cnt < $task_cnt) {
 print STDERR "ERROR: You only have $node_cnt nodes, but requested layout on $task_cnt nodes.\n";
