[{"doc_id": "doc_5755", "sent_idx": 239, "cleaned_version": 1, "sentence": "When a job is terminating, both the job and its nodes enter the COMPLETING state. As the Slurm daemon on each node determines that all processes associated with the job have terminated, that node changes state to IDLE or some other appropriate state for use by other jobs."}, {"doc_id": "doc_5755", "sent_idx": 243, "cleaned_version": 1, "sentence": "This may be indicative of processes hung waiting for a core file to complete I/O or operating system failure. If this state persists, the system administrator should check for processes associated with the job that cannot be terminated then use the scontrol command to change the node's state to DOWN (e.g. "scontrol update NodeName=name State=DOWN Reason=hung_completing"), reboot the node, then reset the node's state to IDLE (e.g. "scontrol update NodeName=name State=RESUME")."}, {"doc_id": "doc_7425", "sent_idx": 75, "cleaned_version": 1, "sentence": "[];
