Added.paths["/slurmdb/v0.0.42/qos/"].post.parameters[5].schema.enum ="}, {"doc_id": "doc_c8a9", "sent_idx": 53, "cleaned_version": 1, "sentence": "Specifies minimum run time of jobs before they are considered for preemption. This is only honored when the PreemptMode is set to REQUEUE or CANCEL. It is specified as a time string: A time of -1 disables the option, equivalent to 0."}, {"doc_id": "doc_c8a9", "sent_idx": 74, "cleaned_version": 1, "sentence": "When a heterogeneous job is to be preempted the first identified component of the job with the highest order PreemptMode (SUSPEND (highest), REQUEUE, CANCEL (lowest)) will be used to set the PreemptMode for all components."}, {"doc_id": "doc_c8a9", "sent_idx": 76, "cleaned_version": 1, "sentence": "Because licenses are not freed when jobs are suspended, jobs using licenses requested by higher priority jobs will only be prempted when PreemptMode is either REQUEUE or CANCEL and PreemptParameters=reclaim_licenses is set."}]

